import re
pats={'gh_token':r'gh[pousr]_[A-Za-z0-9]{20,}','github_pat':r'github_pat_[A-Za-z0-9_]{40,}','google_AIza':r'AIza[0-9A-Za-z_-]{30,}','sk-':r'(?<![A-Za-z0-9_-])sk-[A-Za-z0-9_-]{20,}','slack':r'xox[baprs]-[A-Za-z0-9-]{10,}','apikey_':r'apikey_[A-Za-z0-9]{20,}','KEY=':r'(KEY|TOKEN|SECRET|PASSWORD)[A-Z_]*=["\']?[A-Za-z0-9_\-]{16,}'}
t=open('projects/-Users-kristinarash-DEV/b1b9233e-a07b-48f3-aed1-abea0104e565.jsonl',errors='ignore').read()
for k,p in pats.items():
  ms=re.findall(r'.{0,0}'+p,t) if False else [m.group(0) for m in re.finditer(p,t)]
