    print(k,len(ms))
    for m in set(ms): print('   ',m[:6]+'…'+f'(len {len(m)})', 'ctx:', re.sub(r'[A-Za-z0-9_\-]{12,}','<X>',t[max(0,t.find(m)-60):t.find(m)]).replace('\\n',' ')[-60:])
EOF

