input.command:
cd ~/.claude && python3 - <<'EOF'
import re,subprocess
files=[l[3:] for l in subprocess.run(['git','status','--porcelain','-uall','projects/'],capture_output=True,text=True).stdout.splitlines()]
P=r'gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{40,}|AIza[0-9A-Za-z_-]{30,}|(?<![A-Za-z0-9_-])sk-[A-Za-z0-9_-]{20,}|xox[baprs]-[A-Za-z0-9-]{10,}|apikey_[A-Za-z0-9]{20,}|(KEY|TOKEN|SECRET|PASSWORD)[A-Z_]*=["\']?[A-Za-z0-9_\-]{16,}'
for f in files:
  t=open(f,errors='ignore').read()
  hits={m.group(0)[:5]+'…' for m in re.finditer(P,t)}
  if hits: print(f.split('/')[-1][:20], sorted(hits)[:6])
print('scanned',len(files))
EOF

